function evidence = f90_xbatt05_extract_reference_evidence( ...
        modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XBATT05_EXTRACT_REFERENCE_EVIDENCE Replay the exact current reference.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end

assert(isfile(modelPath), "SimuVerity:F90:XBATT05:ModelMissing", ...
    "Reference model is missing: %s", modelPath);
assert(isfile(officialScenarios), "SimuVerity:F90:XBATT05:OfficialScenarios", ...
    "Official scenarios are missing: %s", officialScenarios);
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XBATT05:ReferenceAssetRoot", ...
    "Evaluator-owned reference asset root is missing: %s", evaluatorAssetRoot);

expectedPresence = lower(strtrim(string("present")));
assert(strlength(expectedPresence) > 0, "SimuVerity:F90:XBATT05:ReferenceBinding", ...
    "The evaluator reference file presence binding is missing or invalid.");
assert(localFilePresence(modelPath) == expectedPresence, ...
    "SimuVerity:F90:XBATT05:ReferenceIdentity", ...
    "Reference file presence differs from the task binding.");

referenceRoot = fullfile(evaluatorAssetRoot, "src");
localValidateReferenceClosure(referenceRoot, expectedPresence);
official = localOfficialScenarios(officialScenarios);

assert(~isfolder(outputDir), "SimuVerity:F90:XBATT05:OutputReuse", ...
    "Reference evidence output directory already exists: %s", outputDir);
mkdir(outputDir);
cacheDir = fullfile(outputDir, "cache");
codegenDir = fullfile(outputDir, "codegen");
mkdir(cacheDir);
mkdir(codegenDir);
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(genpath(referenceRoot), "-begin");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
scoringRunId = string(getenv("SIMUVERITY_SCORING_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XBATT05:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(strlength(scoringRunId) > 0, "SimuVerity:F90:XBATT05:ScoringRunId", ...
    "SIMUVERITY_SCORING_RUN_ID is required.");

evidencePath = fullfile(outputDir, "evidence.json");
sourcePresenceBefore = localFilePresence(modelPath);
evidence = struct( ...
    "schema", "simuverity.f90-xbatt05-evidence.v1", ...
    "task_id", "F90-XBATT-05", ...
    "evaluation_subject", "reference", ...
    "reference_identity_applicable", true, ...
    "reference_subject", true, ...
    "source_model", modelPath, ...
    "source_model_file_presence", sourcePresenceBefore, ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "model_closed_without_save", false, ...
    "reference_binding_preserved", false, ...
    "EVIDENCE_COMPLETE", false, ...
    "evidence_complete", false, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "scoring_run_id", scoringRunId, ...
        "matlab_release", string(version("-release")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));
localWriteJson(evidencePath, evidence);

model = "";
try
    modelHandle = load_system(modelPath);
    model = string(get_param(modelHandle, "Name"));
    assert(model == "TSPMeA_AdvancedCharger", ...
        "SimuVerity:F90:XBATT05:ReferenceModelName", ...
        "Unexpected reference model name: %s", model);
    evidence.load_pass = true;
    assert(str2double(get_param(model, "StopTime")) == ...
        double(official.simulation.stop_time_s), ...
        "SimuVerity:F90:XBATT05:StopTime", "Pinned native stop time changed.");
    assert(str2double(get_param(model, "MaxStep")) == ...
        double(official.simulation.max_step_s), ...
        "SimuVerity:F90:XBATT05:MaxStep", "Pinned native maximum step changed.");

    localInstallTaps(model);
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "off", ...
        "SaveOutput", "off", ...
        "SaveState", "off", ...
        "SimscapeLogType", "none", ...
        "LimitDataPoints", "off");
    localApplyScenario(model, official.scenarios(1));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model, referenceRoot);
    localWriteJson(evidencePath, evidence);

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).class = string(scenario.class);
        rows(k).requested_inputs = scenario;
        try
            localApplyScenario(model, scenario);
            set_param(model, "SimulationCommand", "update");
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut);
            rows(k) = localFinalizeScenario(rows(k), outputs);
            clear simOut outputs
        catch ME
            rows(k).error = localError(ME);
        end
        evidence.scenarios = rows;
        localWriteJson(evidencePath, evidence);
    end

    evidence.nominal_smoke_pass = rows(1).valid;
    assert(all([rows.valid]), "SimuVerity:F90:XBATT05:ScenarioEvidence", ...
        "One or more fixed reference scenarios did not produce valid evidence.");
    localCloseModel(model);
    evidence.model_closed_without_save = ~bdIsLoaded(model);
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourcePresenceBefore;
    assert(evidence.reference_binding_preserved, ...
        "SimuVerity:F90:XBATT05:ReferenceModified", ...
        "Reference extraction modified the current model file.");
    evidence.EVIDENCE_COMPLETE = evidence.load_pass && ...
        evidence.update_pass && evidence.compile_pass && ...
        evidence.nominal_smoke_pass && ...
        evidence.static_audit.core_path_qualified && ...
        all([evidence.scenarios.valid]) && ...
        evidence.model_closed_without_save && ...
        evidence.reference_binding_preserved;
    evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
    assert(evidence.EVIDENCE_COMPLETE, "SimuVerity:F90:XBATT05:EvidenceIncomplete", ...
        "Reference extraction did not satisfy the evidence-lock prerequisites.");
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
catch ME
    try
        if strlength(model) > 0
            feval(model, [], [], [], "term");
        end
    catch
    end
    localCloseModel(model);
    evidence.model_closed_without_save = ...
        strlength(model) == 0 || ~bdIsLoaded(model);
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourcePresenceBefore;
    evidence.EVIDENCE_COMPLETE = false;
    evidence.evidence_complete = false;
    evidence.errors.session = localError(ME);
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
    rethrow(ME)
end

fprintf("F90_XBATT05_REFERENCE_EVIDENCE load=%d update=%d compile=%d valid=%d/%d complete=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    sum([evidence.scenarios.valid]), numel(evidence.scenarios), ...
    evidence.EVIDENCE_COMPLETE, evidencePath);
end

function official = localOfficialScenarios(pathValue)
official = jsondecode(fileread(pathValue));
assert(isstruct(official) && isfield(official, "schema") && ...
    string(official.schema) == "simuverity.official-scenarios.v1", ...
    "SimuVerity:F90:XBATT05:ScenarioSchema", ...
    "Unexpected official scenario schema.");
assert(isfield(official, "task_id") && ...
    string(official.task_id) == "F90-XBATT-05", ...
    "SimuVerity:F90:XBATT05:ScenarioTask", ...
    "Official scenarios are bound to a different task.");
expectedIds = ["nominal", "low_initial_soc", "high_initial_soc", ...
    "cold_cell_and_ambient", "warm_cell_and_ambient", ...
    "hot_weak_heat_rejection", "hot_strong_heat_rejection"];
actualIds = string({official.scenarios.id});
assert(isequal(actualIds(:).', expectedIds), ...
    "SimuVerity:F90:XBATT05:ScenarioContract", ...
    "Official scenario IDs or order differ from the task binding.");
requiredFields = ["initial_soc", "initial_temperature_C", ...
    "ambient_temperature_C", "heat_transfer_coefficient_W_per_m2K"];
for k = 1:numel(official.scenarios)
    row = official.scenarios(k);
    for name = requiredFields
        assert(isfield(row, name) && isscalar(row.(name)) && ...
            isfinite(double(row.(name))), ...
            "SimuVerity:F90:XBATT05:ScenarioInput", ...
            "Scenario %s has an invalid %s input.", string(row.id), name);
    end
end
assert(isfield(official, "simulation") && ...
    double(official.simulation.stop_time_s) == 1e6 && ...
    double(official.simulation.max_step_s) == 5, ...
    "SimuVerity:F90:XBATT05:SimulationContract", ...
    "Official simulation settings differ from the task binding.");
end

function localValidateReferenceClosure(referenceRoot, expectedPresence)
assert(isfolder(referenceRoot), "SimuVerity:F90:XBATT05:ReferenceClosure", ...
    "Reference dependency root is missing: %s", referenceRoot);
required = [ ...
    fullfile(referenceRoot, "Examples", "simpleExamples", ...
        "TSPMeA_AdvancedCharger.slx"), ...
    fullfile(referenceRoot, "+BatteryLibrary", "+Models", ...
        "TSPMeA.ssc"), ...
    fullfile(referenceRoot, "+BatteryLibrary", "+Utilities", ...
        "ControlledElectricalSource.ssc"), ...
    fullfile(referenceRoot, "BatteryLibrary_lib.slx")];
for pathValue = required
    assert(isfile(pathValue), "SimuVerity:F90:XBATT05:ReferenceIncomplete", ...
        "Reference dependency is missing: %s", pathValue);
end
assert(localFilePresence(required(1)) == expectedPresence, ...
    "SimuVerity:F90:XBATT05:ReferenceClosureIdentity", ...
    "Evaluator asset closure contains a different reference model.");
end

function localInstallTaps(model)
scope = model + "/Scope";
localTap(scope, scope + "/From", "f90_cell_current_A");
localTap(scope, scope + "/From1", "f90_cell_voltage_V");
localTap(scope, scope + "/From2", "f90_cell_temperature_K");
localTap(scope, scope + "/From3", "f90_cell_soc");
localTap(scope, scope + "/From4", "f90_potentials_V");
localTap(scope, scope + "/From5", "f90_film_um");
localTap(scope, scope + "/From6", "f90_capacity_soh");
localTap(scope, scope + "/From7", "f90_capacity_losses");
localTap(scope, scope + "/From8", "f90_porosity");
localTap(model, model + "/Advanced_cycling", ...
    "f90_charger_input_type", 1);
localTap(model, model + "/Advanced_cycling", ...
    "f90_charger_command", 2);
localTap(model, model + "/Advanced_cycling", ...
    "f90_cycle_count", 3);
end

function localTap(parent, source, variable, portIndex)
if nargin < 4, portIndex = 1; end
tap = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(tap) < 0, ...
    "SimuVerity:F90:XBATT05:TapCollision", ...
    "Temporary measurement tap already exists.");
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries", ...
    "MaxDataPoints", "inf");
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
assert(numel(sourcePorts.Outport) >= portIndex && ...
    sourcePorts.Outport(portIndex) > 0 && tapPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XBATT05:TapPort", "A required real source port is missing.");
add_line(parent, sourcePorts.Outport(portIndex), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(model, scenario)
localSetPhysicalParameter(model + "/TSPMeA", "z0", ...
    double(scenario.initial_soc), "1");
localSetPhysicalParameter(model + "/TSPMeA", "T0", ...
    double(scenario.initial_temperature_C), "degC");
localSetPhysicalParameter(model + "/Temperature Source", "temperature", ...
    double(scenario.ambient_temperature_C), "degC");
localSetPhysicalParameter(model + "/Convective Heat" + newline + ...
    "Transfer", "heat_tr_coeff", ...
    double(scenario.heat_transfer_coefficient_W_per_m2K), ...
    "W/(m^2 * K)");
end

function localSetPhysicalParameter(block, parameter, value, unit)
set_param(block, parameter, sprintf("%.17g", value));
unitParameter = parameter + "_unit";
dialog = get_param(block, "DialogParameters");
if isfield(dialog, char(unitParameter))
    set_param(block, unitParameter, unit);
end
end

function outputs = localExtractOutputs(simOut)
current = localSeries(simOut, "f90_cell_current_A", 1);
voltage = localSeries(simOut, "f90_cell_voltage_V", 1);
temperature = localSeries(simOut, "f90_cell_temperature_K", 1);
soc = localSeries(simOut, "f90_cell_soc", 1);
potentials = localSeries(simOut, "f90_potentials_V", 3);
film = localSeries(simOut, "f90_film_um", 1);
capacitySoh = localSeries(simOut, "f90_capacity_soh", 1);
losses = localSeries(simOut, "f90_capacity_losses", 2);
porosity = localSeries(simOut, "f90_porosity", 1);
inputType = localSeries(simOut, "f90_charger_input_type", 1);
command = localSeries(simOut, "f90_charger_command", 1);
cycleCount = localSeries(simOut, "f90_cycle_count", 1);

allSeries = {current, voltage, temperature, soc, potentials, film, ...
    capacitySoh, losses, porosity, inputType, command, cycleCount};
starts = cellfun(@(x) x.time(1), allSeries);
ends = cellfun(@(x) x.time(end), allSeries);
startTime = max(starts);
endTime = min(ends);
assert(endTime > startTime, "SimuVerity:F90:XBATT05:EvidenceOverlap", ...
    "Required physical signals have no common interval.");
time = linspace(startTime, endTime, 5000)';
currentValues = localInterp(current, time, "previous");
voltageValues = localInterp(voltage, time, "linear");
temperatureValues = localInterp(temperature, time, "linear") - 273.15;
socValues = localInterp(soc, time, "linear");
commandValues = localInterp(command, time, "previous");
phaseCode = localPhaseCode(commandValues);
cycleValues = localInterp(cycleCount, time, "previous");
actualPower = voltageValues .* currentValues;

outputs = struct( ...
    "time_s", time, ...
    "cell_state", [voltageValues, currentValues, ...
        temperatureValues, socValues], ...
    "charger_state", [phaseCode, commandValues, ...
        actualPower, cycleValues], ...
    "electrochemical_state", [ ...
        localInterp(potentials, time, "linear"), ...
        localInterp(film, time, "linear"), ...
        localInterp(porosity, time, "linear"), ...
        localInterp(capacitySoh, time, "linear"), ...
        localInterp(losses, time, "linear")], ...
    "native_sample_counts", struct( ...
        "current", numel(current.time), ...
        "voltage", numel(voltage.time), ...
        "temperature", numel(temperature.time), ...
        "soc", numel(soc.time), ...
        "potentials", numel(potentials.time), ...
        "film", numel(film.time), ...
        "capacity_soh", numel(capacitySoh.time), ...
        "capacity_losses", numel(losses.time), ...
        "porosity", numel(porosity.time), ...
        "input_type", numel(inputType.time), ...
        "command", numel(command.time), ...
        "cycle_count", numel(cycleCount.time)));
end

function code = localPhaseCode(command)
code = zeros(size(command));
code(abs(command + 5) <= 1e-5) = 1;
code(abs(command - 5) <= 1e-5) = 2;
code(abs(command - 4.2) <= 1e-5) = 3;
end

function series = localSeries(simOut, name, channels)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XBATT05:OutputMissing", ...
    "Required Timeseries %s is missing.", name);
time = double(value.Time(:));
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data, 1) ~= numel(time) && size(data, 2) == numel(time)
    data = data.';
end
assert(size(data, 1) == numel(time) && size(data, 2) == channels, ...
    "SimuVerity:F90:XBATT05:OutputShape", ...
    "Unexpected shape for %s; expected %d channels.", name, channels);
[time, index] = unique(time, "stable");
data = data(index, :);
assert(numel(time) >= 2 && all(isfinite(time)) && ...
    all(isfinite(data), "all"), "SimuVerity:F90:XBATT05:OutputInvalid", ...
    "Required signal %s is incomplete or nonfinite.", name);
series = struct("time", time, "values", data);
end

function values = localInterp(series, time, method)
values = interp1(series.time, series.values, time, method, "extrap");
if isvector(values), values = values(:); end
end

function row = localFinalizeScenario(row, outputs)
values = [outputs.time_s; outputs.cell_state(:); ...
    outputs.charger_state(:); outputs.electrochemical_state(:)];
row.simulation_pass = true;
row.required_evidence_pass = ...
    all(isfinite(values)) && ...
    outputs.time_s(1) == 0 && ...
    outputs.time_s(end) >= 1e6 - 1 && ...
    size(outputs.cell_state, 2) == 4 && ...
    size(outputs.charger_state, 2) == 4 && ...
    size(outputs.electrochemical_state, 2) == 8;
row.outputs = outputs;
row.metrics = localMetrics(outputs);
row.valid = row.required_evidence_pass && ...
    row.metrics.full_sequence_pass;
row.error = struct;
end

function metrics = localMetrics(outputs)
t = outputs.time_s;
cellState = outputs.cell_state;
charger = outputs.charger_state;
electrochem = outputs.electrochemical_state;
phase = charger(:,1);
command = charger(:,2);
voltage = cellState(:,1);
current = cellState(:,2);
temperature = cellState(:,3);
soc = cellState(:,4);

cpStart = localFirstTime(t, phase == 1, -Inf);
restAfterCp = localFirstTime(t, phase == 0, cpStart + 100);
ccStart = localFirstTime(t, phase == 2, restAfterCp + 100);
cvStart = localFirstTime(t, phase == 3, ccStart + 100);
finalRest = localFirstTime(t, phase == 0, cvStart + 100);
sequencePass = all(isfinite([cpStart, restAfterCp, ccStart, ...
    cvStart, finalRest])) && ...
    cpStart < restAfterCp && restAfterCp < ccStart && ...
    ccStart < cvStart && cvStart < finalRest;

cpMask = localFirstPhaseMask(t, phase == 1, cpStart, restAfterCp);
ccMask = localFirstPhaseMask(t, phase == 2, ccStart, cvStart);
cvMask = localFirstPhaseMask(t, phase == 3, cvStart, finalRest);
cvIndices = find(cvMask);
if isempty(cvIndices)
    cvInitialCurrent = NaN;
    cvFinalCurrent = NaN;
else
    head = cvIndices(1:min(10, numel(cvIndices)));
    tail = cvIndices(max(1, end-9):end);
    cvInitialCurrent = median(abs(current(head)));
    cvFinalCurrent = median(abs(current(tail)));
end
metrics = struct( ...
    "full_sequence_pass", sequencePass, ...
    "cp_start_s", cpStart, ...
    "rest_after_cp_s", restAfterCp, ...
    "cc_start_s", ccStart, ...
    "cv_start_s", cvStart, ...
    "final_rest_start_s", finalRest, ...
    "cp_power_median_W", localMedian(charger(cpMask,3)), ...
    "cp_power_relative_error", ...
        abs(localMedian(charger(cpMask,3)) + 5) / 5, ...
    "cc_current_median_A", localMedian(current(ccMask)), ...
    "cc_current_relative_error", ...
        abs(localMedian(current(ccMask)) - 5) / 5, ...
    "cv_voltage_median_V", localMedian(voltage(cvMask)), ...
    "cv_voltage_absolute_error_V", ...
        abs(localMedian(voltage(cvMask)) - 4.2), ...
    "cv_initial_current_A", cvInitialCurrent, ...
    "cv_final_current_A", cvFinalCurrent, ...
    "cv_taper_ratio", cvFinalCurrent / max(cvInitialCurrent, eps), ...
    "voltage_min_V", min(voltage), ...
    "voltage_max_V", max(voltage), ...
    "temperature_min_C", min(temperature), ...
    "temperature_max_C", max(temperature), ...
    "soc_min", min(soc), ...
    "soc_max", max(soc), ...
    "completed_sequence_count", max(charger(:,4)), ...
    "film_growth_um", electrochem(end,4) - electrochem(1,4), ...
    "porosity_change", electrochem(end,5) - electrochem(1,5), ...
    "capacity_soh_change", electrochem(end,6) - electrochem(1,6), ...
    "sei_capacity_loss_change", electrochem(end,7) - electrochem(1,7), ...
    "plating_capacity_loss_change", electrochem(end,8) - electrochem(1,8), ...
    "command_values", unique(command).');
end

function mask = localFirstPhaseMask(time, phaseMask, startTime, endTime)
mask = phaseMask & time >= startTime & time < endTime;
end

function value = localFirstTime(time, mask, threshold)
index = find(mask & time > threshold + 1e-9, 1, "first");
if isempty(index), value = NaN; else, value = time(index); end
end

function value = localMedian(values)
if isempty(values), value = NaN; else, value = median(values); end
end

function audit = localStaticAudit(model, referenceRoot)
chart = model + "/Advanced_cycling";
source = model + "/Controlled" + newline + "Electrical Source";
chartPorts = get_param(chart, "PortHandles");
audit = struct( ...
    "cell_component_path", string(get_param( ...
        model + "/TSPMeA", "ComponentPath")), ...
    "controlled_source_component_path", string(get_param( ...
        source, "ComponentPath")), ...
    "charger_is_stateflow", strcmp(get_param(chart, "SFBlockType"), "Chart"), ...
    "charger_input_port_count", numel(chartPorts.Inport), ...
    "charger_output_port_count", numel(chartPorts.Outport), ...
    "convective_heat_transfer_present", ...
        getSimulinkBlockHandle(model + "/Convective Heat" + ...
            newline + "Transfer") > 0, ...
    "temperature_source_present", ...
        getSimulinkBlockHandle(model + "/Temperature Source") > 0, ...
    "physical_current_sensor_present", ...
        getSimulinkBlockHandle(model + "/ampMeter") > 0, ...
    "physical_voltage_sensor_present", ...
        getSimulinkBlockHandle(model + "/voltMeter") > 0, ...
    "measurement_feedback_connected", ...
        localChartInputsConnected(chart), ...
    "command_actuator_connected", ...
        localChartOutputsConnected(chart, source), ...
    "required_custom_source_files_present", ...
        isfile(fullfile(referenceRoot, "+BatteryLibrary", ...
            "+Models", "TSPMeA.ssc")));
audit.cell_component_qualified = ...
    audit.cell_component_path == "BatteryLibrary.Models.TSPMeA";
audit.controlled_source_qualified = ...
    audit.controlled_source_component_path == ...
        "BatteryLibrary.Utilities.ControlledElectricalSource";
audit.core_path_qualified = ...
    audit.cell_component_qualified && ...
    audit.controlled_source_qualified && ...
    audit.charger_is_stateflow && ...
    audit.charger_input_port_count == 2 && ...
    audit.charger_output_port_count >= 2 && ...
    audit.convective_heat_transfer_present && ...
    audit.temperature_source_present && ...
    audit.physical_current_sensor_present && ...
    audit.physical_voltage_sensor_present && ...
    audit.measurement_feedback_connected && ...
    audit.command_actuator_connected && ...
    audit.required_custom_source_files_present;
end

function pass = localChartInputsConnected(chart)
ports = get_param(chart, "PortHandles");
pass = numel(ports.Inport) == 2;
for port = ports.Inport(:)'
    line = get_param(port, "Line");
    pass = pass && line > 0 && get_param(line, "SrcPortHandle") > 0;
end
end

function pass = localChartOutputsConnected(chart, source)
chartPorts = get_param(chart, "PortHandles");
model = string(bdroot(char(chart)));
converterType = model + "/Simulink-PS" + newline + "Converter1";
converterSignal = model + "/Simulink-PS" + newline + "Converter";
pass = getSimulinkBlockHandle(source) > 0 && ...
    numel(chartPorts.Outport) >= 2 && ...
    localOutputFeedsBlock(chartPorts.Outport(1), converterType) && ...
    localOutputFeedsBlock(chartPorts.Outport(2), converterSignal);
end

function pass = localOutputFeedsBlock(port, expectedBlock)
line = get_param(port, "Line");
if line <= 0
    pass = false;
    return
end
destinations = get_param(line, "DstPortHandle");
blocks = arrayfun(@(x) get_param(x, "Parent"), destinations, ...
    "UniformOutput", false);
pass = any(strcmp(blocks, char(expectedBlock)));
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "class", "", ...
    "requested_inputs", struct, ...
    "simulation_wall_clock_s", 0, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "outputs", struct, ...
    "metrics", struct, ...
    "error", struct);
end

function value = localGetOutput(simOut, name)
try
    value = simOut.get(name);
catch
    value = [];
end
if isempty(value) && evalin("base", sprintf("exist('%s','var')", name))
    value = evalin("base", name);
end
end

function localCloseModel(model)
try
    if strlength(model) > 0 && bdIsLoaded(model)
        close_system(model, 0);
    end
catch
end
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message));
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w");
assert(fid > 0, "SimuVerity:F90:XBATT05:JsonWrite", ...
    "Could not open JSON output: %s", pathValue);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
